class Hayvan:
  def __init__(self, isim):
    self.isim = isim
  def yemek_ye(self):
    print(self.isim + ' yemek yiyor.')

h = Hayvan('Bir hayvan')
h.yemek_ye()

class Hayvan:
  def nefes_al(self):
    print('Nefes alınıyor...')

# Kopek, Hayvan sınıfından miras alıyor
class Kopek(Hayvan):
  pass # Şimdilik içi boş

karabas = Kopek()
karabas.nefes_al() # Ebeveynin metodunu kullanabildi

class Baba:
  def __init__(self):
    print('Baba sınıfı başlatıldı')

class Cocuk(Baba):
  def __init__(self):
    print('Çocuk sınıfı başlatıldı (Babanınki ezildi)')

c = Cocuk()

class Hayvan:
  def __init__(self, tur):
    self.tur = tur

class Kedi(Hayvan):
  def __init__(self, isim):
    super().__init__('Kedi Türü') # Üst sınıfı çalıştır
    self.isim = isim

k = Kedi('Pamuk')
print(k.isim, 'bir', k.tur)

class Kus:
  def ses_cikar(self):
    print('Cik cik')

class Karga(Kus):
  def ses_cikar(self):
    print('Gaaak gaaak') # Üst sınıfı ezdik

k = Karga()
k.ses_cikar()
